export let nanoid = (size = 21) => {
  let id = ''
  let bytes = crypto.getRandomValues(new Uint8Array((size |= 0)))
  while (size--) {
    // The following mask reduces the random byte in the 0-255 value
    // range to the 0-63 value range.
    id += urlAlphabet[bytes[size] & 63]
  }
  return id
}

export let nanoid = (size = 21) => {
  let id = ''
  // A compact alternative for `for (var i = 0; i < step; i++)`.
  // `> 0` stops a negative size from looping forever.
  let i = size | 0
  while (i-- > 0) {
    // `| 0` is more compact and faster than `Math.floor()`.
    id += urlAlphabet[(Math.random() * 64) | 0]
  }
  return id
}

test('throws on negative or too big ID length', () => {
  throws(() => {
    nanoid(2147483648)
  }, /Wrong ID size|Invalid typed array length/)
  throws(() => {
    nanoid(-10)
  }, /Wrong ID size|Invalid typed array length/)
  let a = nanoid()
  let b = nanoid()
  notEqual(a, b)
})

test('does not hang on negative size (nanoid)', () => {
  equal(nanoid(-1), '')
  equal(nanoid(-100), '')
})

test(`generates IDs bigger than pool size`, () => {
  let id = nanoid(70000)
  equal(id.length, 70000)
  for (let char of id) {
    match(urlAlphabet, new RegExp(char, 'g'))
  }
})

test(`changes ID length`, () => {
  equal(nanoid(10).length, 10)
})

test(`accepts string`, () => {
  equal(nanoid('10').length, 10)
})

test(`generates large IDs`, () => {
  let id = nanoid(1000)
  equal(id.length, 1000)
  for (let char of id) {
    match(urlAlphabet, new RegExp(char, 'g'))
  }
})

